    const bucket = weight <= 0 ? 0 : 2 ** Math.ceil(Math.log2(weight));
    buckets.set(bucket, (buckets.get(bucket) ?? 0) + 1);
  }
  return [...buckets].sort(([a], [b]) => a - b);
}
